APPEND_ONLY = """
CREATE OR REPLACE FUNCTION cbt_{name}_are_append_only() RETURNS trigger AS $$
BEGIN
    RAISE EXCEPTION
        'cbt_{table} is append-only; % is not allowed. {why}', TG_OP
        USING ERRCODE = 'restrict_violation';
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER cbt_{name}_are_append_only
BEFORE UPDATE OR DELETE ON cbt_{table}
FOR EACH ROW EXECUTE FUNCTION cbt_{name}_are_append_only();
"""

DROP_APPEND_ONLY = """
DROP TRIGGER IF EXISTS cbt_{name}_are_append_only ON cbt_{table};
DROP FUNCTION IF EXISTS cbt_{name}_are_append_only();
"""

