    dict(name="release_restores", table="testreleaserestore", why="It is the record of who restored a release, and why."),
    dict(name="released_test_scores", table="releasedtestscore", why="A released score never changes."),
    dict(name="ca_transfers", table="catransfer", why="It is the record of each send to CA."),
