BEFORE_RELEASE = """
CREATE OR REPLACE FUNCTION cbt_a_key_is_corrected_only_before_release() RETURNS trigger AS $$
DECLARE
    live integer;
BEGIN
    EXECUTE format(
        'SELECT count(*) FROM %I.cbt_testrelease r WHERE r.test_id = $1 AND NOT EXISTS '
        '(SELECT 1 FROM %I.cbt_testreleaserestore x WHERE x.release_id = r.id)',
        TG_TABLE_SCHEMA, TG_TABLE_SCHEMA)
        INTO live USING NEW.test_id;
    IF live > 0 THEN
        RAISE EXCEPTION
            'a_key_is_corrected_only_before_release: this test has released scores; a key is corrected only before release, or after the principal restores it.'
            USING ERRCODE = 'restrict_violation';
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER cbt_a_key_is_corrected_only_before_release
BEFORE INSERT ON cbt_keycorrection
FOR EACH ROW EXECUTE FUNCTION cbt_a_key_is_corrected_only_before_release();
"""

